sys_script.script:
(function executeRule(current, previous) {

    var REQUEST =
        'x_snc_campus360_mock_interview_slot_request';

    var AVAILABILITY =
        'x_snc_campus360_trainer_interview_availability';

    var REQUEST_TRAINER =
        'x_snc_campus360_mock_interview_request_trainer';

    var MOCK_INTERVIEW =
        'x_snc_campus360_mock_interview';

    var NOTIFICATION =
        'x_snc_campus360_student_notification';


    /* =====================================================
       HELPERS
       ===================================================== */

    function validField(gr, field) {

        return gr &&
               gr.isValidField(field);

    }


    function choiceValue(
        table,
        field,
        label
    ) {

        var ch =
            new GlideRecord('sys_choice');

        ch.addQuery(
            'name',
            table
        );

        ch.addQuery(
            'element',
            field
        );

        ch.addQuery(
            'label',
            label
        );

        ch.addQuery(
            'inactive',
            false
        );

        ch.setLimit(1);

        ch.query();

        if (ch.next()) {

            return String(
                ch.getValue('value')
            );

        }

        return '';

    }


    function getValue(
        gr,
        field
    ) {

        if (
            !validField(
                gr,
                field
            )
        ) {

            return '';

        }

        return String(
            gr.getValue(field) || ''
        );

    }


    /* =====================================================
       ONLY PROCESS ACCEPTED
       ===================================================== */

    var acceptedValue =
        choiceValue(
            REQUEST_TRAINER,
            'response',
            'Accepted'
        );


    if (!acceptedValue) {
        return;
    }


    if (
        getValue(
            current,
            'response'
        ) !== acceptedValue
    ) {

        return;

    }


    /*
     * Prevent a second trainer from winning after
     * another trainer has already accepted.
     */

    var requestId =
        getValue(
            current,
            'request'
        );

    var trainerId =
        getValue(
            current,
            'trainer'
        );


    if (!requestId || !trainerId) {
        return;
    }


    var request =
        new GlideRecord(
            REQUEST
        );


    if (!request.get(requestId)) {
        return;
    }


    var acceptedRequestValue =
        choiceValue(
            REQUEST,
            'status',
            'Accepted'
        );


    var requestedRequestValue =
        choiceValue(
            REQUEST,
            'status',
            'Requested'
        );


    /*
     * If the parent request is already accepted,
     * this trainer is not the winner.
     */

    if (
        acceptedRequestValue &&
        getValue(
            request,
            'status'
        ) === acceptedRequestValue
    ) {

        /*
         * Keep this assignment Pending if it is not
         * the accepted trainer.
         */

        if (
            getValue(
                request,
                'accepted_trainer'
            ) !== trainerId
        ) {

            var pendingValue =
                choiceValue(
                    REQUEST_TRAINER,
                    'response',
                    'Pending'
                );

            if (
                pendingValue &&
                validField(
                    current,
                    'response'
                )
            ) {

                current.setValue(
                    'response',
                    pendingValue
                );

                current.update();

            }

        }

        return;

    }


    /* =====================================================
       FIND REQUESTED TIMING
       ===================================================== */

    var timingId = '';


    if (
        validField(
            request,
            'requested_timing'
        )
    ) {

        timingId =
            getValue(
                request,
                'requested_timing'
            );

    }


    if (
        !timingId &&
        validField(
            request,
            'selected_availability'
        )
    ) {

        timingId =
            getValue(
                request,
                'selected_availability'
            );

    }


    if (
        !timingId &&
        validField(
            request,
            'selected_slot'
        )
    ) {

        timingId =
            getValue(
                request,
                'selected_slot'
            );

    }


    if (!timingId) {
        return;
    }


    var selectedAvailability =
        new GlideRecord(
            AVAILABILITY
        );


    if (
        !selectedAvailability.get(
            timingId
        )
    ) {

        return;

    }


    var selectedDate =
        getValue(
            selectedAvailability,
            'available_date'
        );

    var startTime =
        getValue(
            selectedAvailability,
            'start_time'
        );

    var endTime =
        getValue(
            selectedAvailability,
            'end_time'
        );

    var interviewType =
        getValue(
            selectedAvailability,
            'interview_type'
        );

    var skillArea =
        getValue(
            selectedAvailability,
            'skill_area'
        );


    /* =====================================================
       1. PARENT REQUEST = ACCEPTED
       ===================================================== */

    if (
        acceptedRequestValue &&
        validField(
            request,
            'status'
        )
    ) {

        request.setValue(
            'status',
            acceptedRequestValue
        );

    }


    if (
        validField(
            request,
            'accepted_trainer'
        )
    ) {

        request.setValue(
            'accepted_trainer',
            trainerId
        );

    }


    if (
        validField(
            request,
            'accepted_on'
        )
    ) {

        request.setValue(
            'accepted_on',
            new GlideDateTime().getValue()
        );

    }


    request.update();


    /* =====================================================
       2. BOOK ALL MATCHING AVAILABILITY ROWS
       ===================================================== */

    var bookedValue =
        choiceValue(
            AVAILABILITY,
            'status',
            'Booked'
        );


    if (bookedValue) {

        var matchingAvailability =
            new GlideRecord(
                AVAILABILITY
            );


        matchingAvailability.addQuery(
            'available_date',
            selectedDate
        );

        matchingAvailability.addQuery(
            'start_time',
            startTime
        );

        matchingAvailability.addQuery(
            'end_time',
            endTime
        );

        matchingAvailability.addQuery(
            'interview_type',
            interviewType
        );

        matchingAvailability.addQuery(
            'skill_area',
            skillArea
        );

        matchingAvailability.addQuery(
            'active',
            true
        );

        matchingAvailability.query();


        while (
            matchingAvailability.next()
        ) {

            matchingAvailability.setValue(
                'status',
                bookedValue
            );

            matchingAvailability.update();

        }

    }


    /* =====================================================
       3. KEEP OTHER TRAINERS FROM ACCEPTING
       ===================================================== */

    var otherAssignments =
        new GlideRecord(
            REQUEST_TRAINER
        );


    otherAssignments.addQuery(
        'request',
        requestId
    );


    otherAssignments.addQuery(
        'sys_id',
        '!=',
        current.getUniqueValue()
    );


    otherAssignments.query();


    var pendingValue =
        choiceValue(
            REQUEST_TRAINER,
            'response',
            'Pending'
        );


    while (
        otherAssignments.next()
    ) {

        /*
         * Only reset other Accepted records.
         */

        if (
            getValue(
                otherAssignments,
                'response'
            ) === acceptedValue
        ) {

            if (pendingValue) {

                otherAssignments.setValue(
                    'response',
                    pendingValue
                );

                otherAssignments.update();

            }

        }

    }


    /* =====================================================
       4. LINK EXISTING MOCK INTERVIEW
       ===================================================== */

    var mock =
        new GlideRecord(
            MOCK_INTERVIEW
        );


    if (
        validField(
            mock,
            'slot_request'
        )
    ) {

        /*
         * First try an existing Mock Interview
         * already associated with the same student,
         * trainer and date.
         */

        mock.addQuery(
            'student',
            getValue(
                request,
                'student'
            )
        );

        mock.addQuery(
            'trainer',
            trainerId
        );

        if (
            validField(
                mock,
                'interview_date'
            )
        ) {

            mock.addQuery(
                'interview_date',
                selectedDate
            );

        }

        mock.setLimit(1);

        mock.query();


        if (mock.next()) {

            mock.setValue(
                'slot_request',
                requestId
            );

            mock.update();

        }

    }


    /* =====================================================
       5. IF NO MOCK INTERVIEW EXISTS, CREATE ONE
       ===================================================== */

    var linkedMockId = '';


    var existingMock =
        new GlideRecord(
            MOCK_INTERVIEW
        );


    if (
        validField(
            existingMock,
            'slot_request'
        )
    ) {

        existingMock.addQuery(
            'slot_request',
            requestId
        );

        existingMock.setLimit(1);

        existingMock.query();


        if (existingMock.next()) {

            linkedMockId =
                existingMock.getUniqueValue();

        }

    }


    /*
     * Create a Mock Interview if there isn't one.
     *
     * This is what guarantees that the accepted
     * request gets a Slot Request relationship.
     */

    if (!linkedMockId) {

        var newMock =
            new GlideRecord(
                MOCK_INTERVIEW
            );

        newMock.initialize();


        if (
            validField(
                newMock,
                'slot_request'
            )
        ) {

            newMock.setValue(
                'slot_request',
                requestId
            );

        }


        if (
            validField(
                newMock,
                'student'
            )
        ) {

            newMock.setValue(
                'student',
                getValue(
                    request,
                    'student'
                )
            );

        }


        if (
            validField(
                newMock,
                'trainer'
            )
        ) {

            newMock.setValue(
                'trainer',
                trainerId
            );

        }


        if (
            validField(
                newMock,
                'interview_date'
            )
        ) {

            newMock.setValue(
                'interview_date',
                selectedDate
            );

        }


        if (
            validField(
                newMock,
                'start_time'
            )
        ) {

            newMock.setValue(
                'start_time',
                startTime
            );

        }


        if (
            validField(
                newMock,
                'end_time'
            )
        ) {

            newMock.setValue(
                'end_time',
                endTime
            );

        }


        if (
            validField(
                newMock,
                'interview_type'
            )
        ) {

            newMock.setValue(
                'interview_type',
                interviewType
            );

        }


        /*
         * Scheduled status if that choice exists.
         */

        var scheduledValue =
            choiceValue(
                MOCK_INTERVIEW,
                'interview_status',
                'Scheduled'
            );


        if (
            scheduledValue &&
            validField(
                newMock,
                'interview_status'
            )
        ) {

            newMock.setValue(
                'interview_status',
                scheduledValue
            );

        }


        if (
            validField(
                newMock,
                'qr_status'
            )
        ) {

            var generatedValue =
                choiceValue(
                    MOCK_INTERVIEW,
                    'qr_status',
                    'Generated'
                );

            if (generatedValue) {

                newMock.setValue(
                    'qr_status',
                    generatedValue
                );

            }

        }


        var newMockId =
            newMock.insert();


        /*
         * If the record was created successfully,
         * connect it back to the parent.
         */

        if (newMockId) {

            linkedMockId =
                newMockId;

        }

    }


    /* =====================================================
       6. STORE MOCK INTERVIEW REFERENCE ON REQUEST
       ===================================================== */

    if (
        linkedMockId &&
        validField(
            request,
            'mock_interview'
        )
    ) {

        /*
         * Reload because the request was updated earlier.
         */

        var requestReload =
            new GlideRecord(
                REQUEST
            );

        if (
            requestReload.get(
                requestId
            )
        ) {

            requestReload.setValue(
                'mock_interview',
                linkedMockId
            );

            requestReload.update();

        }

    }


    /* =====================================================
       7. STUDENT NOTIFICATION
       ===================================================== */

    var studentId =
        getValue(
            request,
            'student'
        );


    if (studentId) {

        var notification =
            new GlideRecord(
                NOTIFICATION
            );

        notification.initialize();


        if (
            validField(
                notification,
                'student'
            )
        ) {

            notification.setValue(
                'student',
                studentId
            );

        }


        if (
            validField(
                notification,
                'message'
            )
        ) {

            notification.setValue(
                'message',
                'Your mock interview request ' +
                request.getDisplayValue() +
                ' has been accepted. ' +
                'Your interview is scheduled for ' +
                selectedDate +
                ' from ' +
                startTime +
                ' to ' +
                endTime +
                '.'
            );

        }


        if (
            validField(
                notification,
                'sent_date'
            )
        ) {

            notification.setValue(
                'sent_date',
                new GlideDateTime().getValue()
            );

        }


        /*
         * Populate notification choices only
         * when those choices actually exist.
         */

        if (
            validField(
                notification,
                'status'
            )
        ) {

            var unreadValue =
                choiceValue(
                    NOTIFICATION,
                    'status',
                    'Unread'
                );

            if (!unreadValue) {

                unreadValue =
                    choiceValue(
                        NOTIFICATION,
                        'status',
                        'New'
                    );

            }

            if (unreadValue) {

                notification.setValue(
                    'status',
                    unreadValue
                );

            }

        }


        if (
            validField(
                notification,
                'notification_type'
            )
        ) {

            var mockType =
                choiceValue(
                    NOTIFICATION,
                    'notification_type',
                    'Mock Interview'
                );

            if (mockType) {

                notification.setValue(
                    'notification_type',
                    mockType
                );

            }

        }


        if (
            validField(
                notification,
                'action_required'
            )
        ) {

            notification.setValue(
                'action_required',
                true
            );

        }


        notification.insert();

    }


})(current, previous);
